// The owner's Omnigent password (WP3.31, manual step 11): generated by `run` when none is given,
// and put on the clipboard with the platform's own tool (wl-copy on Wayland, xclip or xsel on
// X11, pbcopy on macOS), as the staging harness's `run.sh password` does. The person stores it in
// their password manager and presses Enter; only then does the run go on to upload it.
//
// The password is never printed, logged, put in argv or the environment, or written to disk: it
// reaches the clipboard tool on its stdin only, and the platform Worker as a secret (machine.ts).
// The clipboard tool is started with nothing but stdin, so a tool that stays in the background
// to serve the clipboard (wl-copy, xclip, xsel) holds none of the bootstrap's locks.
//
// The fallbacks are the existing ones: a prompt, typed twice, where there is no clipboard tool,
// it fails, or the person asks to choose (--password-prompt); `--secrets-stdin`, read by
// bootstrap.ts; and outside a terminal, a refusal that names --secrets-stdin.

import { spawnSync } from "node:child_process";
import { accessSync, constants } from "node:fs";
import { delimiter, join } from "node:path";
import { passwordProblem } from "./settings.ts";

/** Letters and digits without the look-alikes (0 O 1 l I): easy to read back if ever needed. */
export const PASSWORD_ALPHABET = "ABCDEFGHJKLMNPQRSTUVWXYZabcdefghijkmnopqrstuvwxyz23456789";
/** 24 characters of 57: about 140 bits. */
export const PASSWORD_LENGTH = 24;

/** A password of PASSWORD_LENGTH characters, uniform over the alphabet (rejection sampling). */
export function generatePassword(random: (bytes: number) => Uint8Array): string {
  const n = PASSWORD_ALPHABET.length;
  const limit = 256 - (256 % n);
  let password = "";
  while (password.length < PASSWORD_LENGTH) {
    for (const byte of random(PASSWORD_LENGTH)) {
      if (byte < limit && password.length < PASSWORD_LENGTH)
        password += PASSWORD_ALPHABET[byte % n];
    }
  }
  return password;
}

export interface ClipboardTool {
  readonly command: string;
  readonly args: readonly string[];
}

/** Whether `command` is an executable file in one of PATH's directories. */
export function onPath(command: string, env: NodeJS.ProcessEnv = process.env): boolean {
  return (env.PATH ?? "")
    .split(delimiter)
    .filter((dir) => dir !== "")
    .some((dir) => {
      try {
        accessSync(join(dir, command), constants.X_OK);
        return true;
      } catch {
        return false;
      }
    });
}

/** The platform's clipboard tool, or undefined where there is none (a server, an SSH session). */
export function clipboardTool(
  env: NodeJS.ProcessEnv = process.env,
  platform: NodeJS.Platform = process.platform,
  has: (command: string) => boolean = (command) => onPath(command, env),
): ClipboardTool | undefined {
  if (platform === "darwin") return has("pbcopy") ? { command: "pbcopy", args: [] } : undefined;
  if (env.WAYLAND_DISPLAY && has("wl-copy")) return { command: "wl-copy", args: [] };
  if (env.DISPLAY) {
    if (has("xclip")) return { command: "xclip", args: ["-selection", "clipboard"] };
    if (has("xsel")) return { command: "xsel", args: ["--clipboard", "--input"] };
  }
  return undefined;
}

/**
 * Puts `text` on the clipboard through the tool's stdin, and says whether that worked. The tool
 * gets stdin and nothing else: no descriptor of ours, no output to wait for.
 */
export function copyToClipboard(tool: ClipboardTool, text: string): boolean {
  const child = spawnSync(tool.command, [...tool.args], {
    input: text,
    stdio: ["pipe", "ignore", "ignore"],
    timeout: 10_000,
  });
  return child.error === undefined && child.status === 0;
}

/** What `ownerPassword` needs of the terminal and the platform. */
export interface PasswordIo {
  readonly isTTY: boolean;
  /** Reads a line without echoing it. */
  readonly prompt: (question: string) => Promise<string>;
  /** Shows a line, then waits for Enter. */
  readonly confirm: (question: string) => Promise<void>;
  readonly say: (line: string) => void;
  readonly clipboard: ClipboardTool | undefined;
  readonly copy: (tool: ClipboardTool, text: string) => boolean;
  readonly random: (bytes: number) => Uint8Array;
}

export interface PasswordOptions {
  /** The person chooses it (--password-prompt). */
  readonly choose: boolean;
  /** Where the owner signs in, and as whom: for the instruction. */
  readonly hostname: string;
  readonly username: string;
  /** An earlier run made a password that never reached the installation. */
  readonly replaces: boolean;
}

/** The owner's password for the first deploy: generated onto the clipboard, or typed. */
export async function ownerPassword(io: PasswordIo, options: PasswordOptions): Promise<string> {
  if (!io.isTTY) {
    throw new Error("the owner's password is needed: run in a terminal, or use --secrets-stdin");
  }
  if (!options.choose && io.clipboard !== undefined) {
    const password = generatePassword(io.random);
    if (io.copy(io.clipboard, password)) {
      io.say(
        `The owner's Omnigent password is on your clipboard (it is not shown${options.replaces ? "; it replaces the one an earlier, unfinished run gave you, which never reached the installation" : ""}). Store it in your password manager now: the owner signs in to Omnigent at https://${options.hostname} as ${options.username} with it.`,
      );
      await io.confirm("Press Enter once it is stored: ");
      return password;
    }
    io.say(
      `Could not put the password on the clipboard (${io.clipboard.command}); choose one instead.`,
    );
  }
  const password = await io.prompt("The owner's Omnigent password (not shown): ");
  const problem = passwordProblem(password);
  if (problem) throw new Error(problem);
  if ((await io.prompt("Again: ")) !== password) throw new Error("the passwords differ");
  return password;
}
